  let shown = 'en';
  function apply(lang) {
    const key = lang === 'nl' ? 'nl' : 'en';
    const page = key === 'nl' ? dutch[slug] : english;
    if (!page || key === shown) return;
    shown = key;
    document.documentElement.lang = key;
    document.title = page.docTitle;
    if (el.title)      el.title.innerHTML = page.title;
    if (el.category)   el.category.textContent = page.category;
    if (el.date)       el.date.textContent = page.date;
    if (el.read)       el.read.textContent = page.read;
    if (el.current)    el.current.textContent = page.current;
    if (el.link)       el.link.textContent = page.articlesLink;
    if (el.cover)      el.cover.alt = page.coverAlt;
    if (el.ctaTitle)   el.ctaTitle.innerHTML = page.bottomTitle;
    if (el.ctaText)    el.ctaText.textContent = page.bottomText;
    if (el.ctaPrimary) el.ctaPrimary.textContent = page.bottomPrimaryBtn;
    if (el.ctaSecond)  el.ctaSecond.textContent = page.bottomSecondaryBtn;
    if (el.related)    el.related.textContent = page.relatedTitle;
    contentEl.innerHTML = page.content;
  }

  document.addEventListener('wk:languagechange', e => apply(e?.detail?.lang || localStorage.getItem('wk-lang') || 'en'));
